namespace ghidra.app.plugin.core.string.translate;




using docking.action;
using ghidra.app;
using ghidra.app.plugin;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool.util;
using ghidra.program.model.listing;

/**
 * Plugin that provides string translation services on {@link Data} items that are
 * strings or arrays of chars.
 */
//@formatter:off
/* @PluginInfo(
	status = PluginStatus.RELEASED,
	packageName = CorePluginPackage.NAME,
	category = PluginCategoryNames.COMMON,
	shortDescription = "String translation",
	description = "Allows the user to use string translation services.",
	servicesProvided = { typeof(StringTranslationService) }
) */
//@formatter:on

public class TranslateStringsPlugin : Plugin {

	private List<DockingAction> translationActions = new();
	private List<StringTranslationService> translationServices = new();

	public TranslateStringsPlugin(PluginTool tool) : base(tool)
    {
		setupServices();
	}

	/* @Override */
	protected void init() {
		createTranslateActions(StringTranslationService.getCurrentStringTranslationServices(tool));
		createTranslateMetaActions();
	}

	private void setupServices() {
		registerServiceProvided(typeof(StringTranslationService),
			new ManualStringTranslationService());
	}

	private void createTranslateMetaActions() {
		tool.addAction(new ClearTranslationAction(getName()));
		tool.addAction(new ToggleShowTranslationAction(getName()));
	}

	private void createTranslateActionsIfNeeded() {
		List<StringTranslationService> newServices =
			StringTranslationService.getCurrentStringTranslationServices(tool);
		bool isSame = newServices.containsAll(translationServices) &&
			translationServices.containsAll(newServices);

		if (!isSame) {
			createTranslateActions(newServices);
		}
	}

	private void createTranslateActions(List<StringTranslationService> newServices) {
		foreach (DockingAction prevAction in translationActions) {
			tool.removeAction(prevAction);
		}
		translationActions.clear();
		translationServices.clear();

		translationServices.addAll(newServices);

		foreach (StringTranslationService service in translationServices) {
			DockingAction action = new TranslateAction(getName(), service);
			translationActions.add(action);
			tool.addAction(action);
		}
	}

	/* @Override */
	public void serviceAdded(Class<object> interfaceClass, object service) {
		createTranslateActionsIfNeeded();
	}

	/* @Override */
	public void serviceRemoved(Class<object> interfaceClass, object service) {
		createTranslateActionsIfNeeded();
	}

}
